#!/bin/bash
set -euo pipefail

ROOT="$(cd "$(dirname "$0")/.." && pwd)"
cd "$ROOT"

version="$(git describe --tags --exact-match HEAD 2>/dev/null || git rev-parse --short HEAD)"
output="$ROOT/Sources/Nyathing/Version.swift"
cat > "$output" <<EOF
// Generated by Scripts/generate-version.sh. Do not edit.
enum AppVersion {
  static let current = "$version"
}
EOF
